function minSquaredGaps(a: number[], b: number[], k1: number, k2: number): number {
  const d = a.map((x, i) => Math.abs(x - b[i]));
  let k = k1 + k2;
  if (d.reduce((s, x) => s + x, 0) <= k) return 0;
  const cost = (t: number) => d.reduce((s, x) => s + Math.max(0, x - t), 0);
  let lo = 0, hi = Math.max(...d);
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (cost(mid) <= k) hi = mid; else lo = mid + 1;
  }
  const t = lo;
  k -= cost(t);
  let score = 0;
  for (const x of d) {
    let g = Math.min(x, t);
    if (g === t && k > 0) { g--; k--; } // leftover moves go to gaps at level t
    score += g * g;
  }
  return score;
}

