class Solution:
    def minSquaredGaps(self, a: List[int], b: List[int], k1: int, k2: int) -> int:
        d = [abs(x - y) for x, y in zip(a, b)]
        k = k1 + k2
        if sum(d) <= k:
            return 0

        def cost(t):
            return sum(x - t for x in d if x > t)

        lo, hi = 0, max(d)
        while lo < hi:
            mid = (lo + hi) // 2
            if cost(mid) <= k:
                hi = mid
            else:
                lo = mid + 1
        t = lo
        k -= cost(t)
        score = 0
        for x in d:
            g = min(x, t)
            if g == t and k > 0:
                g -= 1
                k -= 1
            score += g * g
        return score

