function minSquaredGaps(a, b, k1, k2) {
  const d = a.map((x, i) => Math.abs(x - b[i]));
  let k = k1 + k2;
  if (d.reduce((s, x) => s + x, 0) <= k) return 0;
  const cost = (t2) => d.reduce((s, x) => s + Math.max(0, x - t2), 0);
  let lo = 0, hi = Math.max(...d);
  while (lo < hi) {
    const mid = lo + hi >> 1;
    if (cost(mid) <= k) hi = mid;
    else lo = mid + 1;
  }
  const t = lo;
  k -= cost(t);
  let score = 0;
  for (const x of d) {
    let g = Math.min(x, t);
    if (g === t && k > 0) {
      g--;
      k--;
    }
    score += g * g;
  }
  return score;
}
